import yaml

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/registry.yaml', 'r') as f:
    data = yaml.safe_load(f)

experiments = data.get('experiments', [])

# 1. qwen14b_teal30_uniform_4task
# 2. mistral + (hellaswag|piqa|downstream)
# 3. qwen14b_kl30_s123

targets = {}
mistral_matches = []

for exp in experiments:
    eid = exp.get('exp_id', '')
    if eid == 'qwen14b_teal30_uniform_4task':
        targets['qwen14b_teal30_uniform_4task'] = exp
    if eid == 'qwen14b_kl30_s123':
        targets['qwen14b_kl30_s123'] = exp
    if 'mistral' in eid.lower():
        eid_lower = eid.lower()
        if any(kw in eid_lower for kw in ['hellaswag', 'piqa', 'downstream']):
            mistral_matches.append(exp)

import json

def dump_exp(exp):
    fields = ['exp_id', 'status', 'conclusion', 'metrics', 'server', 'checkpoint_path', 'log_path', 'hypothesis', 'parent']
    result = {}
    for f in fields:
        if f in exp:
            result[f] = exp[f]
    # spec.command
    spec = exp.get('spec', {})
    if spec:
        result['spec'] = spec
    return result

print('=' * 80)
print('1. qwen14b_teal30_uniform_4task')
print('=' * 80)
if 'qwen14b_teal30_uniform_4task' in targets:
    print(yaml.dump(dump_exp(targets['qwen14b_teal30_uniform_4task']), default_flow_style=False, allow_unicode=True, width=200))
else:
